'use strict';

// "Model answers from Daniel" for Writing Task 1 (WritingTask1 docs), plus
// the colour-coded sentence roles shown on writing.html — same mechanism
// as Task 2 (sampleSections[].highlights, see task2SampleHighlights.js).
//
// Task 1 roles / codes:
//   Introduction  Q = paraphrase (giới thiệu biểu đồ — viết lại đề)
//   Overview      O = overview (đặc điểm nổi bật, không số liệu)
//   Body          T = topic sentence (câu dẫn nhóm dữ liệu của đoạn)
//                 D = detail (số liệu / bước / thay đổi cụ thể)
//                 C = comparison (so sánh, đối chiếu giữa các đối tượng)
// Every sentence of every section carries a role.
//
// Applied by scripts/seedTask1DanielSamples.js (keyed by WritingTask1 _id):
//   SAMPLES   — written into docs whose sample is missing or has a blank
//               section (essays read off each chart image, following that
//               doc's "Phân tích đề").
//   ANALYSES  — "Phân tích đề" for docs that have none, or that still carry
//               the generic placeholder ("1. Dạng bài & cách làm").
//   TEXT_FIXES — exact-string corrections in existing text.
//   SPECS     — sentence-index role specs for the existing essays
//               [intro, overview, body1, body2], indexed after TEXT_FIXES.

